    "business_card_topic_bp_1_0": {
      "decoDesc": "请向前走吧，崭新的、无限的世界正等待着您。",
      "name": "启程"
    },
    "business_card_topic_chr_0009_azrila": {
      "decoDesc": "坚硬的血和炽热的钢在北地筑成堡垒。那里不是她的梦魇，那里仍是下一个终点。",
      "name": "不落坚城"
    },
    "business_card_topic_chr_0013_aglina": {
      "decoDesc": "将视野倒转，你会发现不一样的景色、不一样的心情、不一样的自己。世界变成了崭新的。",
      "name": "世界翻转"
    },
    "business_card_topic_chr_0015_lifeng": {
      "decoDesc": "如璞玉，千琢而不晦。",
      "name": "少年心"
    },
    "business_card_topic_chr_0016_laevat": {
      "decoDesc": "陪她走进无忆的长夜，陪她焚尽黑暗的梦魇，陪她点燃映照前路的火焰。",
      "name": "熔火之邀"
    },
    "business_card_topic_chr_0017_yvonne": {
      "decoDesc": "亮丽的涂装，轻快的音乐，还有游戏获胜时的笑容……每个开心的时刻，她都记录了下来，与你共享。",
      "name": "Win-Win!"
    },
    "business_card_topic_chr_0025_ardelia": {
      "decoDesc": "冰冷坚硬的岩石上开满了花朵，荒漠充满生机和暖意，悠扬的旋律在耳边哼唱……前辈，这不是梦，对吧？",
      "name": "心愿"
    },
    "business_card_topic_chr_0026_lastrite": {
      "decoDesc": "她还有许多问题等待解答，她还有许多困难需要克服。即便如此，她也一定会完成你给的每一项任务，让更多人找回笑容。",
      "name": "初绽霜花"
    },
    "business_card_topic_chr_0029_pograni": {
      "decoDesc": "硝烟似散非散，千钧之躯落下生与死的棋子；剑锋倚地，支撑着铁誓，亦支撑着守望——此刻，将军。",
      "name": "将军"
    },
    "business_card_topic_normal_1": {
      "decoDesc": "欢迎来到塔卫二，管理员。",
      "name": "默认主题"
    },
    "business_card_topic_normal_2": {
      "decoDesc": "一管针剂、一朵花卉与一声感谢，您伸出了手，大地随即重新连接。",
      "name": "初始连接"
    },
    "business_card_topic_normal_3": {
      "decoDesc": "协议启动，生命的进程已向前迈进，愿您与我们携手前行。",
      "name": "协议行进"
    },
    "chr_0002_endminm": {
      "decoDesc": "管理员的聘用证明。\n“呃，虽然您是管理员，但我想，一些具备仪式感的内容还是必不可少的……”",
      "name": "管理员"
    },
    "chr_0003_endminf": {
      "decoDesc": "管理员的聘用证明。\n“呃，虽然您是管理员，但我想，一些具备仪式感的内容还是必不可少的……”",
      "name": "管理员"
    },
    "chr_0004_pelica": {
      "decoDesc": "佩丽卡的聘用证明。\n“我们的监督如此年轻，却为所有人描绘出了终末地的未来景象。”",
      "name": "佩丽卡"
    },
    "chr_0005_chen": {
      "decoDesc": "陈千语的聘用证明。\n“让我看看……本月陈千语和他人切磋次数增加了……呃……她一定是想通了什么武学关窍。”",
      "name": "陈千语"
    },
    "chr_0006_wolfgd": {
      "decoDesc": "狼卫的聘用证明。\n“在处理开拓区居民及裂地者的相关事宜上，请您相信这位来自狼群的好猎手。”",
      "name": "狼卫"
    },
    "chr_0007_ikut": {
      "decoDesc": "弧光的聘用证明。\n“我很想了解弧光干员作为众生长地游人是如何理解这个世界的……但和她聊天真的存在一定难度。”",
      "name": "弧光"
    },
    "chr_0009_azrila": {
      "decoDesc": "余烬的聘用证明。\n“她仍是利刃与铁壁，她的远征尚未结束。”",
      "name": "余烬"
    },
    "chr_0011_seraph": {
      "decoDesc": "赛希的聘用证明。\n“我想我不得不承认，赛希极为擅长和机械造物相处，虽然我不是很理解她为什么想要一个和我同款的逻辑组件。”",
      "name": "赛希"
    },
    "chr_0012_avywen": {
      "decoDesc": "艾维文娜的聘用证明。\n“她拥有高昂的热情，超乎常人的话术……居然还能同时拥有杰出的武力……”",
      "name": "艾维文娜"
    },
    "chr_0013_aglina": {
      "decoDesc": "洁尔佩塔的聘用证明。\n“繁复的色彩，无限的可能性，还有一丝丝甜味……”",
      "name": "洁尔佩塔"
    },
    "chr_0014_aurora": {
      "decoDesc": "昼雪的聘用证明。\n“‘有昼雪小姐这样可靠的人在嘛’，这是很多干员前往极端环境执行任务前为自己打气的原话。”",
      "name": "昼雪"
    },
    "chr_0015_lifeng": {
      "decoDesc": "黎风的聘用证明。\n“淳朴、真诚、善解人意……我感觉就在我写下这些文字的时间内，黎风说不定又完成了几项额外工作。”",
      "name": "黎风"
    },
    "chr_0016_laevat": {
      "decoDesc": "莱万汀的聘用证明。\n“不必害怕触碰火焰……你只需与她同行，留下难忘的记忆。”",
      "name": "莱万汀"
    },
    "chr_0017_yvonne": {
      "decoDesc": "伊冯的聘用证明。\n“特立独行正是其作为天才的证明，无论是研究项目的走向，还是发现同伴们的闪光点，她总能提供最与众不同的视角。”",
      "name": "伊冯"
    },
    "chr_0018_dapan": {
      "decoDesc": "大潘的聘用证明。\n“大潘干员的亲切态度和幽默谈吐？我想一定是得益于他丰富的职业生涯：厨师、个体摊贩、电工、木工、司机……真是全面。”",
      "name": "大潘"
    },
    "chr_0019_karin": {
      "decoDesc": "秋栗的聘用证明。\n“她不只是一名自荐而来的商学院优秀毕业生，更是胸中奔腾着滚烫热忱的理想主义者。”",
      "name": "秋栗"
    },
    "chr_0020_meurs": {
      "decoDesc": "卡契尔的聘用证明。\n“你是说，这次行动确定有卡契尔先生参与吗？呼，太好了，这下就让人安心多了。”",
      "name": "卡契尔"
    },
    "chr_0021_whiten": {
      "decoDesc": "埃特拉的聘用证明。\n“你可以在任何地方信赖埃特拉，除了生活之中。对了，千万别去尝试她推荐的‘美食’，这是为你好。”",
      "name": "埃特拉"
    },
    "chr_0022_bounda": {
      "decoDesc": "萤石的聘用证明。\n“实际上，没有干员觉得她真的在存心捣乱，但这就是最麻烦的地方。”",
      "name": "萤石"
    },
    "chr_0023_antal": {
      "decoDesc": "安塔尔的聘用证明。\n“以安塔尔干员在源石技艺上的天赋，确实是合适的同行人选……不过最好让他少讲一点冷笑话，耶尔什够冷了。”",
      "name": "安塔尔"
    },
    "chr_0024_deepfin": {
      "decoDesc": "阿列什的聘用证明。\n“闲暇时可以和他一起垂钓，去鳞店挑选当日活鳞、新鲜情报或者下一个上钩的幸运儿。”",
      "name": "阿列什"
    },
    "chr_0025_ardelia": {
      "decoDesc": "艾尔黛拉的聘用证明。\n“跟上她轻快的脚步，聆听大地的低语，治愈这颗星球的病痛与创伤。”",
      "name": "艾尔黛拉"
    },
    "chr_0026_lastrite": {
      "decoDesc": "别礼的聘用证明。\n“请站得再靠前一些，别礼小姐。他们只是来看热闹，您用不着躲到墙角去。”",
      "name": "别礼"
    },
    "chr_0029_pograni": {
      "decoDesc": "骏卫的聘用证明。\n“卫戍文明边塞的黎博利，无论是多么艰难的战况，他总是会在关键时刻，出现在文明需要他出现的位置。”",
      "name": "骏卫"
    },
