    "item_weekraid_tech_6_6": {
      "decoDesc": "录入了“应力回馈”技术相关数据的芯片。或许未来的某一天，在干涉像差的技术获得长足进步后，我们能从这个扭曲协议空间中获得更多“回馈”。",
      "name": "应力回馈芯片"
    },
    "item_wgshoal_1_grass_1_grass_2_1": {
      "decoDesc": "极简单的小零食。那些离开家的人、无法回到故乡的人……往往会在最简单的甜味中窥见几缕旧时光。",
      "name": "小糖画"
    },
    "item_wgslime_1_hsmob_1_grass_2_1": {
      "decoDesc": "弹弹的蔬菜冻。商家会用模具将蔬菜冻特意做成龙泡泡的形状，不存在别的选择，大家都喜欢龙泡泡。噢，多么可爱的龙泡泡。",
      "name": "龙泡泡蔬菜冻"
    },
    "item_wgslime_1_wgthorns_1_1": {
      "decoDesc": "打开瓶盖，喝下去，感受气泡在你的唇齿喉间跳动，最后打个嗝儿，就这么简单。",
      "name": "神秘气泡饮料"
    },
    "item_wgthorns_1_hshog_1_hsmob_1_1": {
      "decoDesc": "十分考验烹饪者厨艺的菜肴。球刺兽的肝脏火候稍过便会和橡胶一般硬。如何让它拥有与新笋相同的口感——这是各位大厨需要首先解决的难题。",
      "name": "油爆“双脆”"
    },
    "item_wpngem_enhance_dust": {
      "decoDesc": "在基质蚀刻环节会使用到的特殊冷却脂。温度极易影响到基质蚀刻的结果，故加工环节需使用造价昂贵的冷却脂。",
      "name": "冷却脂"
    },
    "item_wpnpotentialup_bp": {
      "decoDesc": "记录更多干员使用武器的偏好，聆听他们有关武器的期待……武库工程师们尝试使用通行证这种方式，让终末地的武器研发效率更上一层楼。",
      "name": "协议化武器原型"
    },
    "item_wuling_detector_coin_3": {
      "decoDesc": "清波寨寨民们“手搓”出的定位工具，稍加改造就能拥有探测醚质的能力。\n在接近探测目标后，仪器中的水将猛地沸腾起来，因此需要小心使用。",
      "name": "新锐武陵罗盘"
    },
    "item_wuling_detector_trchest_3": {
      "decoDesc": "使用了息壤技术的小型探测器，能有效确认特殊金属的位置，因此可以被用来寻找储藏箱。\n崭新出厂！熠熠生辉！",
      "name": "新锐武陵探物器"
    },
    "item_xiranite_powder": {
      "decoDesc": "将源石与巨兽力量结合于一处后诞生出的新型源石材料。它撑起了武陵的万家灯火。",
      "name": "息壤"
    },
    "monthlycard_lt_1": {
      "decoDesc": "只需在协议同步器轻轻一扫，后勤部将立刻为您提供海量优惠服务。",
      "name": "月卡兑换凭证"
    },
    "monthlycard_reward_r_1": {
      "decoDesc": "只需在协议同步器轻轻一扫，后勤部将立刻为您提供海量优惠服务。",
      "name": "月卡兑换凭证"
    },
    "preset_cbp_voucher_originium_1": {
      "decoDesc": "一部分终末地干员喜欢将协议通行证称为“许愿单”。传说只要在生日前夜许愿，并在床头放上一些衍质源石，就会有善良的武库小机器人送来令人满意的产品。",
      "name": "通行证申请·源石"
    },
    "preset_cbp_voucher_pay_1": {
      "decoDesc": "“好了，只要在这里签字，您就可以拥有独属于您的定制版协议通行证……嗯？效率？放心吧，必要情况下，我们会空投物资支援的。”",
      "name": "通行证申请·定制"
    },
